    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 11 لا يفوق 5001 هو <span dir=\"ltr\" class=\"expr\">11 × 454</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">11 × 454 = 4994</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">5001 - 4994 = 7</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">7 &lt; 11</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">5001 = 11 × 454 + 7</span>"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 10 و هو زوجي، و 15 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">10 = 5 × 2</span> و <span dir=\"ltr\" class=\"expr\">15 = 5 × 3</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 5 يقسم 10 و يقسم 15"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 5 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">24 = 6 × 4</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">54 = 6 × 9</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">24n + 54 = 6(4n + 9)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">6 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"شرط القسمة على 5","math":"العدد يقبل القسمة على 5 إذا كان رقم آحاده 0 أو 5"},{"quoi":"رقم الآحاد معلوم","math":"رقم آحاد العدد 805a0 هو 0"},{"quoi":"الشرط لا يتعلّق بـ a","math":"الشرط يتعلّق برقم الآحاد وحده، و هو 0 مهما يكن a"},{"quoi":"نستنتج","math":"العدد يقبل القسمة على 5 مهما يكن a"},{"quoi":"الجواب","math":"صواب"}],
