    enonce: "<span class=\"q\">1) </span>أجب بصواب أو خطأ مع التعليل: مهما يكن العدد الصحيح n فإنّ <span dir=\"ltr\" class=\"expr\">64n + 40</span> يقبل القسمة على 8<br><span class=\"q\">2) </span>أجب بصواب أو خطأ مع التعليل: عدد صحيح زوجي و عدد صحيح فردي يكونان دائما أوليين فيما بينهما<br><span class=\"q\">3) </span>أجب بصواب أو خطأ مع التعليل: كلّ عدد صحيح مكوّن من ثلاثة أرقام متتالية هو مضاعف لـ 9<br><span class=\"q\">4) </span>أجب بصواب أو خطأ مع التعليل: مهما يكن الرقم a فإنّ العدد 827a0 يقبل القسمة على 5",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">64 = 8 × 8</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">40 = 8 × 5</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">64n + 40 = 8(8n + 5)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">8 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 18 و هو زوجي، و 45 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">18 = 9 × 2</span> و <span dir=\"ltr\" class=\"expr\">45 = 9 × 5</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 9 يقسم 18 و يقسم 45"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 9 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نسمّي رقم المئات","math":"نسمّي n رقم المئات، فتكون الأرقام n و <span dir=\"ltr\" class=\"expr\">n + 1</span> و <span dir=\"ltr\" class=\"expr\">n + 2</span>"},{"quoi":"شرط القسمة على 9","math":"العدد يقبل القسمة على 9 إذا كان مجموع أرقامه يقبل القسمة على 9"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">n + (n + 1) + (n + 2) = 3n + 3</span>"},{"quoi":"نفكّك المجموع","math":"<span dir=\"ltr\" class=\"expr\">3n + 3 = 3(n + 1)</span>"},{"quoi":"المجموع ليس دائما مضاعفا لـ 9","math":"المجموع <span dir=\"ltr\" class=\"expr\">3(n + 1)</span> ليس دائما مضاعفا لـ 9: مثلا العدد 123"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"شرط القسمة على 5","math":"العدد يقبل القسمة على 5 إذا كان رقم آحاده 0 أو 5"},{"quoi":"رقم الآحاد معلوم","math":"رقم آحاد العدد 827a0 هو 0"},{"quoi":"الشرط لا يتعلّق بـ a","math":"الشرط يتعلّق برقم الآحاد وحده، و هو 0 مهما يكن a"},{"quoi":"نستنتج","math":"العدد يقبل القسمة على 5 مهما يكن a"},{"quoi":"الجواب","math":"صواب"}],
