    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"شرط القسمة على 4","math":"العدد يقبل القسمة على 4 إذا كان العدد المكوّن من رقمي عشراته و آحاده يقبل القسمة على 4"},{"quoi":"رقم الآحاد معلوم","math":"رقم آحاد العدد 613a5 هو 5"},{"quoi":"الشرط يتعلّق بـ a","math":"الشرط يتعلّق برقمي العشرات و الآحاد، أي بالعدد a5 الذي يتغيّر مع a"},{"quoi":"مثال مضادّ","math":"من أجل <span dir=\"ltr\" class=\"expr\">a = 3</span> نجد العدد 61335 الذي لا يقبل القسمة على 4"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نفكّك العبارة","math":"<span dir=\"ltr\" class=\"expr\">n<sup>2</sup> + n = n(n + 1)</span>"},{"quoi":"ما هو العدد الأوّلي","math":"العدد الأوّلي له قاسمان فقط: 1 و نفسه"},{"quoi":"العبارة جداء","math":"العبارة مكتوبة جداء عوامل، فهي ليست أوّلية بصفة عامّة"},{"quoi":"مثال مضادّ","math":"من أجل <span dir=\"ltr\" class=\"expr\">n = 5</span> نجد <span dir=\"ltr\" class=\"expr\">5<sup>2</sup> + 5 = 30</span>"},{"quoi":"نفكّك المثال","math":"<span dir=\"ltr\" class=\"expr\">30 = 5(5 + 1)</span>"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 14 و هو زوجي، و 21 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">14 = 7 × 2</span> و <span dir=\"ltr\" class=\"expr\">21 = 7 × 3</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 7 يقسم 14 و يقسم 21"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 7 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نسمّي رقم المئات","math":"نسمّي n رقم المئات، فتكون الأرقام n و <span dir=\"ltr\" class=\"expr\">n + 1</span> و <span dir=\"ltr\" class=\"expr\">n + 2</span>"},{"quoi":"شرط القسمة على 3","math":"العدد يقبل القسمة على 3 إذا كان مجموع أرقامه يقبل القسمة على 3"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">n + (n + 1) + (n + 2) = 3n + 3</span>"},{"quoi":"نفكّك المجموع","math":"<span dir=\"ltr\" class=\"expr\">3n + 3 = 3(n + 1)</span>"},{"quoi":"المجموع مضاعف لـ 3","math":"المجموع مضاعف لـ 3 مهما يكن n، فالشرط محقّق دائما"},{"quoi":"الجواب","math":"صواب"}],
