  { id: "arith9-9-11", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (6n + 60)/(n + 7)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-7</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 6 + 18/(n + 7)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (6n + 60)/(n + 7)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-7</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 6 + 18/(n + 7)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (6n + 60)/(n + 7)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-7</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 6 + 18/(n + 7)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = 2</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (6n + 60)/(n + 7)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">6(n + 7) = 6n + 42</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">6n + 60 = 6(n + 7) + 18</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(6n + 60)/(n + 7) = (6(n + 7) + 18)/(n + 7)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(6(n + 7) + 18)/(n + 7) = 6(n + 7)/(n + 7) + 18/(n + 7)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">6(n + 7)/(n + 7) = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 6 + 18/(n + 7)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 6 + 18/(n + 7)</span>"},{"quoi":"الشرط","math":"6 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">18/(n + 7)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 7</span> يجب أن يكون قاسما للعدد 18"},{"quoi":"قواسم 18","math":"قواسم 18 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 3 ؛ 6 ؛ 9 ؛ 18</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 7 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -25 ؛ -16 ؛ -13 ؛ -10 ؛ -9 ؛ -8 ؛ -6 ؛ -5 ؛ -4 ؛ -1 ؛ 2 ؛ 11</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 6 + 18/(2 + 7)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">2 + 7 = 9</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">18 : 9 = 2</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">6 + 2 = 8</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(6 × 2 + 60)/(2 + 7) = 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 8</span>"}],
    indice: "اكتب البسط بدلالة n + 7: 6n + 60 = 6(n + 7) + 18" },
  { id: "arith9-9-12", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (5n + 54)/(n + 6)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-6</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 5 + 24/(n + 6)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (5n + 54)/(n + 6)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-6</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 5 + 24/(n + 6)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (5n + 54)/(n + 6)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-6</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 5 + 24/(n + 6)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = -5</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (5n + 54)/(n + 6)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">5(n + 6) = 5n + 30</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">5n + 54 = 5(n + 6) + 24</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(5n + 54)/(n + 6) = (5(n + 6) + 24)/(n + 6)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(5(n + 6) + 24)/(n + 6) = 5(n + 6)/(n + 6) + 24/(n + 6)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">5(n + 6)/(n + 6) = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 5 + 24/(n + 6)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 5 + 24/(n + 6)</span>"},{"quoi":"الشرط","math":"5 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">24/(n + 6)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 6</span> يجب أن يكون قاسما للعدد 24"},{"quoi":"قواسم 24","math":"قواسم 24 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 3 ؛ 4 ؛ 6 ؛ 8 ؛ 12 ؛ 24</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 6 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -30 ؛ -18 ؛ -14 ؛ -12 ؛ -10 ؛ -9 ؛ -8 ؛ -7 ؛ -5 ؛ -4 ؛ -3 ؛ -2 ؛ 0 ؛ 2 ؛ 6 ؛ 18</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 5 + 24/(-5 + 6)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">-5 + 6 = 1</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">24 : 1 = 24</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">5 + 24 = 29</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(5 × -5 + 54)/(-5 + 6) = 29</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 29</span>"}],
    indice: "اكتب البسط بدلالة n + 6: 5n + 54 = 5(n + 6) + 24" },
  { id: "arith9-9-13", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (4n + 60)/(n + 8)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-8</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 4 + 28/(n + 8)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (4n + 60)/(n + 8)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-8</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 4 + 28/(n + 8)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (4n + 60)/(n + 8)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-8</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 4 + 28/(n + 8)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = -1</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (4n + 60)/(n + 8)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">4(n + 8) = 4n + 32</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">4n + 60 = 4(n + 8) + 28</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(4n + 60)/(n + 8) = (4(n + 8) + 28)/(n + 8)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(4(n + 8) + 28)/(n + 8) = 4(n + 8)/(n + 8) + 28/(n + 8)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">4(n + 8)/(n + 8) = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 28/(n + 8)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 28/(n + 8)</span>"},{"quoi":"الشرط","math":"4 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">28/(n + 8)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 8</span> يجب أن يكون قاسما للعدد 28"},{"quoi":"قواسم 28","math":"قواسم 28 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 7 ؛ 14 ؛ 28</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 8 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -36 ؛ -22 ؛ -15 ؛ -12 ؛ -10 ؛ -9 ؛ -7 ؛ -6 ؛ -4 ؛ -1 ؛ 6 ؛ 20</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 28/(-1 + 8)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">-1 + 8 = 7</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">28 : 7 = 4</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">4 + 4 = 8</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(4 × -1 + 60)/(-1 + 8) = 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 8</span>"}],
    indice: "اكتب البسط بدلالة n + 8: 4n + 60 = 4(n + 8) + 28" },
  { id: "arith9-9-14", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 39)/(n + 9)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-9</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 12/(n + 9)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 39)/(n + 9)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-9</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 12/(n + 9)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 39)/(n + 9)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-9</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 12/(n + 9)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = 3</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (3n + 39)/(n + 9)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">3(n + 9) = 3n + 27</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">3n + 39 = 3(n + 9) + 12</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(3n + 39)/(n + 9) = (3(n + 9) + 12)/(n + 9)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(3(n + 9) + 12)/(n + 9) = 3(n + 9)/(n + 9) + 12/(n + 9)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">3(n + 9)/(n + 9) = 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 12/(n + 9)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 12/(n + 9)</span>"},{"quoi":"الشرط","math":"3 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">12/(n + 9)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 9</span> يجب أن يكون قاسما للعدد 12"},{"quoi":"قواسم 12","math":"قواسم 12 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 3 ؛ 4 ؛ 6 ؛ 12</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 9 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -21 ؛ -15 ؛ -13 ؛ -12 ؛ -11 ؛ -10 ؛ -8 ؛ -7 ؛ -6 ؛ -5 ؛ -3 ؛ 3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 12/(3 + 9)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">3 + 9 = 12</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">12 : 12 = 1</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">3 + 1 = 4</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(3 × 3 + 39)/(3 + 9) = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 4</span>"}],
    indice: "اكتب البسط بدلالة n + 9: 3n + 39 = 3(n + 9) + 12" },
  { id: "arith9-9-15", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 19)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 16/(n + 1)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 19)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 16/(n + 1)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 19)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 16/(n + 1)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = 15</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (3n + 19)/(n + 1)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">3(n + 1) = 3n + 3</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">3n + 19 = 3(n + 1) + 16</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(3n + 19)/(n + 1) = (3(n + 1) + 16)/(n + 1)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(3(n + 1) + 16)/(n + 1) = 3(n + 1)/(n + 1) + 16/(n + 1)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">3(n + 1)/(n + 1) = 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 16/(n + 1)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 16/(n + 1)</span>"},{"quoi":"الشرط","math":"3 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">16/(n + 1)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 1</span> يجب أن يكون قاسما للعدد 16"},{"quoi":"قواسم 16","math":"قواسم 16 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 8 ؛ 16</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 1 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -17 ؛ -9 ؛ -5 ؛ -3 ؛ -2 ؛ 0 ؛ 1 ؛ 3 ؛ 7 ؛ 15</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 16/(15 + 1)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">15 + 1 = 16</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">16 : 16 = 1</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">3 + 1 = 4</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(3 × 15 + 19)/(15 + 1) = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 4</span>"}],
    indice: "اكتب البسط بدلالة n + 1: 3n + 19 = 3(n + 1) + 16" },
  { id: "arith9-9-16", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (5n + 50)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 5 + 45/(n + 1)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (5n + 50)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 5 + 45/(n + 1)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (5n + 50)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 5 + 45/(n + 1)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = 14</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (5n + 50)/(n + 1)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">5(n + 1) = 5n + 5</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">5n + 50 = 5(n + 1) + 45</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(5n + 50)/(n + 1) = (5(n + 1) + 45)/(n + 1)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(5(n + 1) + 45)/(n + 1) = 5(n + 1)/(n + 1) + 45/(n + 1)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">5(n + 1)/(n + 1) = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 5 + 45/(n + 1)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 5 + 45/(n + 1)</span>"},{"quoi":"الشرط","math":"5 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">45/(n + 1)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 1</span> يجب أن يكون قاسما للعدد 45"},{"quoi":"قواسم 45","math":"قواسم 45 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 3 ؛ 5 ؛ 9 ؛ 15 ؛ 45</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 1 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -46 ؛ -16 ؛ -10 ؛ -6 ؛ -4 ؛ -2 ؛ 0 ؛ 2 ؛ 4 ؛ 8 ؛ 14 ؛ 44</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 5 + 45/(14 + 1)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">14 + 1 = 15</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">45 : 15 = 3</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">5 + 3 = 8</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(5 × 14 + 50)/(14 + 1) = 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 8</span>"}],
    indice: "اكتب البسط بدلالة n + 1: 5n + 50 = 5(n + 1) + 45" },
  { id: "arith9-9-17", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 41)/(n + 7)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-7</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 20/(n + 7)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 41)/(n + 7)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-7</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 20/(n + 7)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (3n + 41)/(n + 7)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-7</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 3 + 20/(n + 7)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = 3</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (3n + 41)/(n + 7)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">3(n + 7) = 3n + 21</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">3n + 41 = 3(n + 7) + 20</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(3n + 41)/(n + 7) = (3(n + 7) + 20)/(n + 7)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(3(n + 7) + 20)/(n + 7) = 3(n + 7)/(n + 7) + 20/(n + 7)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">3(n + 7)/(n + 7) = 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 20/(n + 7)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 20/(n + 7)</span>"},{"quoi":"الشرط","math":"3 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">20/(n + 7)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 7</span> يجب أن يكون قاسما للعدد 20"},{"quoi":"قواسم 20","math":"قواسم 20 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 5 ؛ 10 ؛ 20</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 7 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -27 ؛ -17 ؛ -12 ؛ -11 ؛ -9 ؛ -8 ؛ -6 ؛ -5 ؛ -3 ؛ -2 ؛ 3 ؛ 13</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 20/(3 + 7)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">3 + 7 = 10</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">20 : 10 = 2</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">3 + 2 = 5</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(3 × 3 + 41)/(3 + 7) = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 5</span>"}],
    indice: "اكتب البسط بدلالة n + 7: 3n + 41 = 3(n + 7) + 20" },
  { id: "arith9-9-18", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (2n + 42)/(n + 5)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-5</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 5)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (2n + 42)/(n + 5)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-5</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 5)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (2n + 42)/(n + 5)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-5</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 5)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = -3</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (2n + 42)/(n + 5)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">2(n + 5) = 2n + 10</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">2n + 42 = 2(n + 5) + 32</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(2n + 42)/(n + 5) = (2(n + 5) + 32)/(n + 5)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(2(n + 5) + 32)/(n + 5) = 2(n + 5)/(n + 5) + 32/(n + 5)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">2(n + 5)/(n + 5) = 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 5)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 5)</span>"},{"quoi":"الشرط","math":"2 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">32/(n + 5)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 5</span> يجب أن يكون قاسما للعدد 32"},{"quoi":"قواسم 32","math":"قواسم 32 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 8 ؛ 16 ؛ 32</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 5 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -37 ؛ -21 ؛ -13 ؛ -9 ؛ -7 ؛ -6 ؛ -4 ؛ -3 ؛ -1 ؛ 3 ؛ 11 ؛ 27</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 2 + 32/(-3 + 5)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">-3 + 5 = 2</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">32 : 2 = 16</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">2 + 16 = 18</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(2 × -3 + 42)/(-3 + 5) = 18</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 18</span>"}],
    indice: "اكتب البسط بدلالة n + 5: 2n + 42 = 2(n + 5) + 32" },
  { id: "arith9-9-19", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (2n + 38)/(n + 3)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-3</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 3)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (2n + 38)/(n + 3)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-3</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 3)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (2n + 38)/(n + 3)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-3</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 3)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = -4</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (2n + 38)/(n + 3)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">2(n + 3) = 2n + 6</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">2n + 38 = 2(n + 3) + 32</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(2n + 38)/(n + 3) = (2(n + 3) + 32)/(n + 3)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(2(n + 3) + 32)/(n + 3) = 2(n + 3)/(n + 3) + 32/(n + 3)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">2(n + 3)/(n + 3) = 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 3)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 2 + 32/(n + 3)</span>"},{"quoi":"الشرط","math":"2 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">32/(n + 3)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 3</span> يجب أن يكون قاسما للعدد 32"},{"quoi":"قواسم 32","math":"قواسم 32 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 8 ؛ 16 ؛ 32</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 3 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -35 ؛ -19 ؛ -11 ؛ -7 ؛ -5 ؛ -4 ؛ -2 ؛ -1 ؛ 1 ؛ 5 ؛ 13 ؛ 29</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 2 + 32/(-4 + 3)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">-4 + 3 = -1</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">32 : -1 = -32</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">2 + -32 = -30</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(2 × -4 + 38)/(-4 + 3) = -30</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = -30</span>"}],
    indice: "اكتب البسط بدلالة n + 3: 2n + 38 = 2(n + 3) + 32" }
